insert into public.place_descriptions(book_id,place_id,collection,name,area,kind,zoom,checked,status,note,method,position_source_id,narrative_source_id,additional_source_id,metadata) values ('ulisse','hodges-figgis-1904','core','Hodges Figgis · 104 Grafton Street','104 Grafton Street · Dublin','historical',16,'2026-11-11','Approximate geographic reference','Stephen recalls looking at a woman outside the shop window on Monday, a brief remembered scene; the marker represents the historic address, not the present branch.','OpenStreetMap building for present-day 104 Grafton Street; NLI invoice and UCD historical photograph document the bookshop at the same civic address. Approximate address reference; no claim of the original shopfront surviving.','03b594f326c411d2c7e02723ba3ee33f83651d70011f2371b2e240b4b509fe5f','f5a318a6281ec879a9c391ba217a6766246c70e5139603c09916c9d3d2e64c0c','728fecf2b865697af5ac37e90c8a0697a8ef61c4d7f89feed3897038b6590bbb','{"positionDescription":{"status":"reviewed","reviewedAt":"2026-11-11","texts":{"it":"Nel 1904 la libreria Hodges Figgis si trovava al 104 di Grafton Street. Il punto indica il sito dell’indirizzo storico, non la sede attuale.","en":"In 1904 Hodges Figgis stood at 104 Grafton Street. The point marks the site of the historical address, not the present shop.","fr":"En 1904, la librairie Hodges Figgis se trouvait au 104 Grafton Street. Le point indique le site de l’adresse historique, et non la librairie actuelle.","es":"En 1904 la librería Hodges Figgis estaba en el número 104 de Grafton Street. El punto señala el lugar de la dirección histórica, no la librería actual."}}}'::jsonb) on conflict do nothing;
insert into public.place_references(book_id,id,section_id,place_id,collection,ordinal,category,scene_text,source_id,metadata) values ('ulisse','3:core:hodges-figgis-1904',3,'hodges-figgis-1904','core',8,'action','Stephen recalls looking at a woman outside the shop window on Monday, a brief remembered scene; the marker represents the historic address, not the present branch.','f5a318a6281ec879a9c391ba217a6766246c70e5139603c09916c9d3d2e64c0c','{"explicitCategory":true}'::jsonb) on conflict do nothing;
insert into public.excerpts(book_id,id,section_id,reference_id,slot,language,type,quote,attribution,text_source_id,rights_source_id,metadata) values ('ulisse','3:core:hodges-figgis-1904:original',3,'3:core:hodges-figgis-1904','original','en','original','What she? The virgin at Hodges Figgis’ window on Monday looking in for one of the alphabet books you were going to write. Keen glance you gave her. Wrist through the braided jesse of her sunshade. She lives in Leeson park with a grief and kickshaws, a lady of letters.','James Joyce · Ulysses · 1922 · Chapter III','f5a318a6281ec879a9c391ba217a6766246c70e5139603c09916c9d3d2e64c0c','21f5ddc16c42981666952e8d2fe36af645a8542aa0034417c672e91792c00cf9','{"highlightTerms":["Hodges Figgis’"],"reviewedAt":"2026-11-11"}'::jsonb) on conflict do nothing;
