insert into public.place_descriptions(book_id,place_id,collection,name,area,kind,zoom,checked,status,note,method,position_source_id,narrative_source_id,additional_source_id,metadata) values ('ulisse','strasburg-terrace','core','Strasburg Terrace','Irishtown · Dublin','street',16,'2026-11-11','Approximate geographic reference','Stephen weighs visiting his aunt and remembers his father mentioning her on Strasburg Terrace; no specific aunt’s house is geographically identified.','OpenStreetMap representative coordinate of the named street; Gunn, Hart and Beck map 6 identifies Strasburg Terrace. The point does not identify the cottage or a particular house.','fa7e1a0730fea44d80d6f30f231cfe43271806401cfaf921b8f10468cd4e2478','f5a318a6281ec879a9c391ba217a6766246c70e5139603c09916c9d3d2e64c0c','bb2484df780a4812cddd575135d25b711cc69d12d87123d0f52bef5283cab88b','{"positionDescription":{"status":"reviewed","reviewedAt":"2026-11-11","texts":{"it":"Breve strada di Irishtown indicata nella guida topografica di Joyce. Il punto rappresenta la strada, senza attribuire un numero civico alla casa della zia.","en":"A short street in Irishtown identified in the Joyce topographical guide. The point represents the street, without assigning a house number to Stephen’s aunt.","fr":"Courte rue d’Irishtown figurant dans le guide topographique de Joyce. Le point représente la rue, sans attribuer de numéro à la maison de la tante.","es":"Calle corta de Irishtown identificada en la guía topográfica de Joyce. El punto representa la calle sin atribuir un número a la casa de la tía."}}}'::jsonb) on conflict do nothing;
insert into public.place_references(book_id,id,section_id,place_id,collection,ordinal,category,scene_text,source_id,metadata) values ('ulisse','3:core:strasburg-terrace',3,'strasburg-terrace','core',9,'mentioned','Stephen weighs visiting his aunt and remembers his father mentioning her on Strasburg Terrace; no specific aunt’s house is geographically identified.','f5a318a6281ec879a9c391ba217a6766246c70e5139603c09916c9d3d2e64c0c','{"explicitCategory":true}'::jsonb) on conflict do nothing;
insert into public.excerpts(book_id,id,section_id,reference_id,slot,language,type,quote,attribution,text_source_id,rights_source_id,metadata) values ('ulisse','3:core:strasburg-terrace:original',3,'3:core:strasburg-terrace','original','en','original','His pace slackened. Here. Am I going to aunt Sara’s or not? My consubstantial father’s voice. Did you see anything of your artist brother Stephen lately? No? Sure he’s not down in Strasburg terrace with his aunt Sally? Couldn’t he fly a bit higher than that, eh?','James Joyce · Ulysses · 1922 · Chapter III','f5a318a6281ec879a9c391ba217a6766246c70e5139603c09916c9d3d2e64c0c','21f5ddc16c42981666952e8d2fe36af645a8542aa0034417c672e91792c00cf9','{"highlightTerms":["Strasburg terrace"],"reviewedAt":"2026-11-11"}'::jsonb) on conflict do nothing;
